        self.assertEqual([t.name for t in kit.get_tools()], [t.name for t in TOOLS if t.name in DEFAULT_TOOLS])
        tools = SocialTapToolkit(SocialTap(api_key=API_KEY, base_url=mock.url), AsyncSocialTap(api_key=API_KEY, base_url=mock.url), tools="all").get_tools()
        self.assertEqual([t.name for t in tools], [t.name for t in TOOLS])
        self.assertEqual(tools[0].description, TOOLS[0].description)
        required = TOOLS[0].input_schema.get("required", [])
        args = {name: "x" for name in required}
        mock.reply(tool_reply({"data": 1}))
        self.assertEqual(json.loads(tools[0].invoke(args)), {"data": 1})
        self.assertEqual(json.loads(mock.requests[0].body)["params"]["arguments"], args)
